                    when 72 => melodia_fsm0_nota_reg <= "100";
                    when 73 => melodia_fsm0_nota_reg <= "011";
                    when 74 => melodia_fsm0_nota_reg <= "011";
                    when 75 => melodia_fsm0_nota_reg <= "011";
                    when 76 => melodia_fsm0_nota_reg <= "011";
                    when 77 => melodia_fsm0_nota_reg <= "010";
                    when 78 => melodia_fsm0_nota_reg <= "010";
                    when 79 => melodia_fsm0_nota_reg <= "001";
                    when 80 => melodia_fsm0_nota_reg <= "001";
                    when 81 => melodia_fsm0_nota_reg <= "001";
                    when 82 => melodia_fsm0_nota_reg <= "001";
                    when 83 => melodia_fsm0_nota_reg <= "000";
                    when 84 => melodia_fsm0_nota_reg <= "010";
                    when 85 => melodia_fsm0_nota_reg <= "001";
                    when 86 => melodia_fsm0_nota_reg <= "000";
                    when 87 => melodia_fsm0_nota_reg <= "001";
                    when 88 => melodia_fsm0_nota_reg <= "010";
                    when 89 => melodia_fsm0_nota_reg <= "010";
