                    when 106 => melodia_fsm0_nota_reg <= "001";
                    when 107 => melodia_fsm0_nota_reg <= "010";
                    when 108 => melodia_fsm0_nota_reg <= "001";
                    when others => melodia_fsm0_nota_reg <= "000";
                end case;
                melodia_fsm0_temporizador <= to_unsigned(0, 27);
                melodia_fsm0_estado <= PLAY;
            elsif (melodia_fsm0_estado = PLAY) then
                if (signed(resize(melodia_fsm0_temporizador, 28)) >= (signed(resize(melodia_fsm0_duracion, 28)) - 1)) then
                    melodia_fsm0_temporizador <= to_unsigned(0, 27);
                    melodia_fsm0_estado <= GAP;
                else
                    melodia_fsm0_temporizador <= (melodia_fsm0_temporizador + 1);
                end if;
            elsif (melodia_fsm0_estado = GAP) then
                if (signed(resize(melodia_fsm0_temporizador, 28)) >= (3000000 - 1)) then
                    melodia_fsm0_temporizador <= to_unsigned(0, 27);
                    if (melodia_fsm0_i = melodia_fsm0_ultimo) then
                        melodia_fsm0_estado <= FIN;
                    else
                        melodia_fsm0_i <= (melodia_fsm0_i + 1);
                        melodia_fsm0_estado <= LOAD;
                    end if;
                else
                    melodia_fsm0_temporizador <= (melodia_fsm0_temporizador + 1);
                end if;
            else
                melodia_fsm0_estado <= IDLE;
                melodia_fsm0_i <= to_unsigned(0, 7);
            end if;
        end if;
    end if;
end process melodia_fsm0_fsm;

melodia_fsm0_salidas: process (melodia_fsm0_estado, melodia_fsm0_nota_reg) is
begin
    m_sonando <= stdl(melodia_fsm0_estado = PLAY);
    m_nota <= melodia_fsm0_nota_reg;
    case melodia_fsm0_estado is
        when IDLE =>
            melodia_fsm0_estado_dbg <= to_unsigned(0, 3);
        when LOAD =>
            melodia_fsm0_estado_dbg <= to_unsigned(1, 3);
        when PLAY =>
            melodia_fsm0_estado_dbg <= to_unsigned(2, 3);
        when GAP =>
            melodia_fsm0_estado_dbg <= to_unsigned(3, 3);
        when others =>
            melodia_fsm0_estado_dbg <= to_unsigned(4, 3);
    end case;
end process melodia_fsm0_salidas;

multiplexor: process (hay_tecla, idx_tecla, m_sonando, m_nota) is
begin
    if bool(hay_tecla) then
        idx_sel <= idx_tecla;
        sonar <= '1';
    elsif bool(m_sonando) then
        idx_sel <= m_nota;
        sonar <= '1';
    else
        idx_sel <= to_unsigned(0, 3);
        sonar <= '0';
    end if;
end process multiplexor;

tabla_divisores0_logica: process (idx_sel) is
begin
    case to_integer(idx_sel) is
        when 0 => tabla_divisores0_divisor <= "101110101010000110";
        when 1 => tabla_divisores0_divisor <= "101001100100011001";
        when 2 => tabla_divisores0_divisor <= "100101000010000101";
        when 3 => tabla_divisores0_divisor <= "100010111101000100";
        when 4 => tabla_divisores0_divisor <= "011111001000111111";
        when 5 => tabla_divisores0_divisor <= "011011101111100100";
        when 6 => tabla_divisores0_divisor <= "011000101101110111";
        when others => tabla_divisores0_divisor <= "010111010101000101";
    end case;
end process tabla_divisores0_logica;

generador_tono0_logica: process (clk) is
begin
    if rising_edge(clk) then
        if (rst_s = '1') then
            generador_tono0_cuenta <= to_unsigned(0, 18);
            generador_tono0_div_reg <= to_unsigned(0, 18);
            generador_tono0_salida <= '0';
        else
            if (not bool(sonar)) then
                generador_tono0_cuenta <= to_unsigned(0, 18);
                generador_tono0_salida <= '0';
                generador_tono0_div_reg <= tabla_divisores0_divisor;
            elsif (tabla_divisores0_divisor /= generador_tono0_div_reg) then
                generador_tono0_div_reg <= tabla_divisores0_divisor;
                generador_tono0_cuenta <= to_unsigned(0, 18);
            elsif (signed(resize(generador_tono0_cuenta, 19)) >= (signed(resize(generador_tono0_div_reg, 19)) - 1)) then
                generador_tono0_cuenta <= to_unsigned(0, 18);
                generador_tono0_salida <= stdl((not bool(generador_tono0_salida)));
            else
                generador_tono0_cuenta <= (generador_tono0_cuenta + 1);
            end if;
        end if;
    end if;
end process generador_tono0_logica;


onda <= generador_tono0_salida;

pwm_volumen0_seleccion: process (sincronizador1_salida) is
begin
    case to_integer(sincronizador1_salida) is
        when 0 => pwm_volumen0_umbral <= "000100000";
        when 1 => pwm_volumen0_umbral <= "001000000";
        when 2 => pwm_volumen0_umbral <= "001100000";
        when 3 => pwm_volumen0_umbral <= "010000000";
        when 4 => pwm_volumen0_umbral <= "010100000";
        when 5 => pwm_volumen0_umbral <= "011000000";
        when 6 => pwm_volumen0_umbral <= "011100000";
        when others => pwm_volumen0_umbral <= "100000000";
    end case;
end process pwm_volumen0_seleccion;

pwm_volumen0_logica: process (clk) is
begin
    if rising_edge(clk) then
        if (rst_s = '1') then
            pwm <= '0';
            pwm_volumen0_cuenta <= to_unsigned(0, 8);
        else
            pwm_volumen0_cuenta <= (pwm_volumen0_cuenta + 1);
            pwm <= stdl(pwm_volumen0_cuenta < pwm_volumen0_umbral);
        end if;
    end if;
end process pwm_volumen0_logica;

registro_salidas: process (clk) is
begin
    if rising_edge(clk) then
        if (rst_s = '1') then
            leds_r <= to_unsigned(0, 8);
            aud_en_r <= '0';
            audio <= '0';
        else
            audio <= stdl(bool(onda) and bool(pwm));
            aud_en_r <= '1';
            if bool(sonar) then
                case to_integer(idx_sel) is
                    when 0 => leds_r <= "00000001";
                    when 1 => leds_r <= "00000010";
                    when 2 => leds_r <= "00000100";
                    when 3 => leds_r <= "00001000";
                    when 4 => leds_r <= "00010000";
                    when 5 => leds_r <= "00100000";
                    when 6 => leds_r <= "01000000";
                    when others => leds_r <= "10000000";
                end case;
            else
                leds_r <= to_unsigned(0, 8);
            end if;
        end if;
    end if;
end process registro_salidas;


tono <= tern_op(cond => bool(audio), if_true => 'Z', if_false => '0');


leds <= leds_r;
led_cancion <= leds_c;
aud_en <= aud_en_r;

end architecture MyHDL;
